sys_variable_value.value:
(function execute(inputs, outputs) {

    var scorer = new ReadinessScorer();

    var result = scorer.calculateScore(inputs.assessment_sys_id);

    outputs.score = result.score;
    outputs.gate = result.gate;

})(inputs, outputs);

